+const { useState, useRef, useId } = React;
+
+function NotificationRadioField({ value, onChange, error, errorRef }) {
+  const helpId = useId();
+  const errorId = useId();
+
+  const options = [
+    { value: "email", label: "Email" },
+    { value: "sms", label: "SMS" },
+    { value: "push", label: "Push Notifications" },
+  ];
+
+  const describedBy = [helpId, error ? errorId : null].filter(Boolean).join(" ");
+
+  return (
+    <div className="form-field">
+      <fieldset aria-describedby={describedBy}>
+        <legend>
+          How do you prefer to receive notifications?
+          <span className="req-mark" aria-hidden="true">*</span>
+        </legend>
+        <p id={helpId} className="field-help">
+          Choose one. You can change this later in settings.
+        </p>
+        <div className="options">
+          {options.map((opt, i) => {
+            const id = `notify-${opt.value}`;
+            return (
+              <label key={opt.value} className="option" htmlFor={id}>
+                <input
+                  id={id}
+                  ref={i === 0 ? errorRef : null}
+                  type="radio"
+                  name="notifications"
+                  value={opt.value}
+                  checked={value === opt.value}
+                  onChange={(e) => onChange(e.target.value)}
+                  required
+                  aria-invalid={error ? "true" : undefined}
+                />
+                <span className="label-text">{opt.label}</span>
+              </label>
+            );
+          })}
+        </div>
+        <p id={errorId} className="error" hidden={!error}>
+          {error ? `Error: ${error}` : ""}
+        </p>
+      </fieldset>
+    </div>
+  );
+}
+
+function NotificationForm() {
+  const [value, setValue] = useState("");
+  const [error, setError] = useState("");
+  const [status, setStatus] = useState("");
+  const firstRadioRef = useRef(null);
+
+  const handleChange = (v) => {
+    setValue(v);
+    if (error) setError("");
+  };
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!value) {
+      setError("Select how you'd like to receive notifications.");
+      setStatus("");
+      requestAnimationFrame(() => firstRadioRef.current?.focus());
+      return;
+    }
+    const labels = { email: "Email", sms: "SMS", push: "Push Notifications" };
+    setError("");
+    setStatus(`Preference saved: ${labels[value]}.`);
+  };
+
+  return (
+    <form noValidate onSubmit={handleSubmit}>
+      <p className="required-note">
+        <span className="req-mark" aria-hidden="true">*</span> Required
+      </p>
+      <NotificationRadioField
+        value={value}
+        onChange={handleChange}
+        error={error}
+        errorRef={firstRadioRef}
+      />
+      <button type="submit" className="submit">Save preference</button>
+      <p className="status" role="status" aria-live="polite" hidden={!status}>
+        {status}
+      </p>
+    </form>
+  );
+}
+
+function App() {
+  return (
+    <div className="card">
+      <h1>Notification preferences</h1>
+      <p className="lede">Tell us the best way to reach you.</p>
+      <NotificationForm />
+    </div>
+  );
+}
+
+const root = ReactDOM.createRoot(document.getElementById("root"));
+root.render(<App />);
+
